def mock_table(fname, rows, foot, cols=("Incoming course", "", "Your equivalent", "Status")):
    trs = ""
    for a, b, st in rows:
        pill = {'ok': '<span class="pill ok"><i class="fa-solid fa-check"></i> Matched</span>',
                'warn': '<span class="pill warn"><i class="fa-solid fa-flag"></i> Review</span>',
                'blue': '<span class="pill blue"><i class="fa-solid fa-circle-info"></i> Elective</span>'}[st]
        trs += '<tr><td>%s</td><td class="arrow">→</td><td>%s</td><td>%s</td></tr>' % (a, b, pill)
    return ('<div class="mock"><div class="mbar"><i class="d"></i><i class="d"></i><i class="d"></i><span class="fn">%s</span></div>'
            '<div class="mbody mock-wrap"><table><thead><tr><th>%s</th><th></th><th>%s</th><th>%s</th></tr></thead><tbody>%s</tbody></table></div>'
            '<div class="foot"><span><i class="fa-solid fa-circle-check"></i> %s</span><span>Ready for review</span></div></div>'
            % (fname, cols[0], cols[2], cols[3], trs, foot))

def mock_bars(fname, rows, foot):
    bars = "".join('<div><span>%s</span><span class="b" style="--w:%d%%"></span><b>%s</b></div>' % (a, w, v) for a, w, v in rows)
    return ('<div class="mock"><div class="mbar"><i class="d"></i><i class="d"></i><i class="d"></i><span class="fn">%s</span></div>'
            '<div class="mbody"><div class="bars">%s</div></div><div class="foot"><span><i class="fa-solid fa-circle-check"></i> %s</span></div></div>' % (fname, bars, foot))

